import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';

import API from '../services/api';

import SummaryCards from '../components/SummaryCards';
import Alerts from '../components/Alerts';
import CostCard from '../components/CostCard';
import Graph from '../components/Graph';

function Dashboard() {

    const [insights, setInsights] = useState(null);
    const [alerts, setAlerts] = useState([]);
    const [cost, setCost] = useState(null);
    const [energyData, setEnergyData] = useState([]);
    const [devices, setDevices] = useState([]);

    useEffect(() => {

        const fetchInsights = async () => {
            try {
                const response = await API.get('/insights');
                setInsights(response.data);
            } catch (error) {
                console.log(error);
            }
        };

        const fetchAlerts = async () => {
            try {
                const response = await API.get('/alerts');
                setAlerts(response.data.alerts);
            } catch (error) {
                console.log(error);
            }
        };

        const fetchCost = async () => {
            try {
                const response = await API.get('/cost');
                setCost(response.data);
            } catch (error) {
                console.log(error);
            }
        };

        const fetchData = async () => {
            try {
                const response = await API.get('/data');
                setEnergyData(response.data);
            } catch (error) {
                console.log(error);
            }
        };

        const fetchDevices = async () => {
            try {
                const response = await API.get('/device');
                setDevices(response.data);
            } catch (error) {
                console.log(error);
            }
        };

        fetchInsights();
        fetchAlerts();
        fetchCost();
        fetchData();
        fetchDevices();

        const interval = setInterval(() => {
            fetchInsights();
            fetchAlerts();
            fetchCost();
            fetchData();
            fetchDevices();
        }, 5000);

        return () => clearInterval(interval);

    }, []);

    const turnOffDevice = async (deviceId) => {
        try {
            await API.post(`/device/${deviceId}/turn-off`);
            setDevices(devices.map(d => d._id === deviceId ? { ...d, status: 'OFF' } : d));
        } catch (error) {
            console.log(error);
        }
    };

    if (!insights) {
        return (
            <div className="text-white p-10">
                Loading Dashboard...
            </div>
        );
    }

    // Group energy readings by device so each device gets its own graph.
    const readingsByDevice = {};
    energyData.forEach((item) => {
        const key = item.device ? item.device._id : 'unknown';
        if (!readingsByDevice[key]) readingsByDevice[key] = [];
        readingsByDevice[key].push(item);
    });

    return (

        <div className="flex min-h-screen bg-dark text-white">

            {/* SIDEBAR */}

            <div className="w-64 bg-black border-r border-border p-6">

                <h1 className="text-2xl font-bold text-primary">
                    EnergyAI
                </h1>

                <div className="mt-10 space-y-4">

                    <div className="bg-primary/20 p-3 rounded-xl">
                        Dashboard
                    </div>

                    <Link to="/devices" className="block text-gray-400 hover:text-white">
                        Devices
                    </Link>

                </div>

            </div>

            {/* MAIN CONTENT */}

            <div className="flex-1 p-8">

                {/* HEADER */}

                <div className="flex justify-between items-center mb-10">

                    <div>

                        <h1 className="text-4xl font-bold">
                            Smart Energy Dashboard
                        </h1>

                        <p className="text-gray-400 mt-2">
                            AI-powered energy monitoring platform
                        </p>

                    </div>

                    <div className="bg-green-500/20 text-green-400 px-4 py-2 rounded-xl">
                        ● System Active
                    </div>

                </div>

                {/* SUMMARY CARDS */}

                <SummaryCards insights={insights} />

                {/* GRID SECTION */}

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mt-8">

                    <div className="lg:col-span-2 space-y-6">
                        {devices.length === 0 && (
                            <div className="bg-card border border-border rounded-2xl p-8 text-gray-400">
                                No devices yet.{' '}
                                <Link to="/devices" className="text-primary hover:underline">
                                    Add your first device
                                </Link>{' '}
                                to start seeing live graphs here.
                            </div>
                        )}

                        {devices.map((device) => {
                            const deviceReadings = readingsByDevice[device._id] || [];
                            const latestPower = deviceReadings.length > 0
                                ? deviceReadings[deviceReadings.length - 1].power
                                : null;
                            const overLimit = latestPower !== null && latestPower > device.powerLimit;

                            return (
                                <div key={device._id}>
                                    <div className="flex justify-between items-center mb-2 px-1">
                                        <div className="flex items-center gap-3">
                                            <span className="font-semibold">{device.name}</span>
                                            <span className={`
                                                px-3 py-1 rounded-full text-xs font-semibold
                                                ${device.status === 'ON'
                                                    ? 'bg-green-500/20 text-green-400'
                                                    : 'bg-gray-500/20 text-gray-400'}
                                            `}>
                                                ● {device.status}
                                            </span>
                                            {overLimit && (
                                                <span className="px-3 py-1 rounded-full text-xs font-semibold bg-red-500/20 text-red-300">
                                                    Over limit ({device.powerLimit}W)
                                                </span>
                                            )}
                                        </div>
                                        {device.status === 'ON' && (
                                            <button
                                                onClick={() => turnOffDevice(device._id)}
                                                className="text-xs bg-red-500/20 text-red-300 px-3 py-1.5 rounded-lg hover:bg-red-500/30"
                                            >
                                                Turn OFF
                                            </button>
                                        )}
                                    </div>

                                    {deviceReadings.length > 0 ? (
                                        <Graph data={deviceReadings} title={`${device.name} - Power Usage`} />
                                    ) : (
                                        <div className="bg-card border border-border rounded-2xl p-6 text-gray-400 text-sm">
                                            No readings from "{device.name}" yet. Waiting for sensor data...
                                        </div>
                                    )}
                                </div>
                            );
                        })}
                    </div>

                    <div>
                        {cost &&
                            <CostCard cost={cost} />
                        }
                    </div>

                </div>

                {/* ALERTS */}

                <div className="mt-8">
                    <Alerts alerts={alerts} />
                </div>

            </div>

        </div>

    );

}

export default Dashboard;
